//! RDKit parity test.
//!
//! Compares every FerrumChem feature that has an RDKit equivalent against the
//! RDKit reference in `tests/data/rdkit_parity_reference.csv` (generated by
//! `scripts/generate_parity_reference.py`), plus per-atom perception
//! (aromaticity, H count, hybridization, ...) and fingerprint bits.
//!
//! Known deviations are tracked per column in `tests/data/rdkit_parity_baseline.tsv`
//! (column -> allowed number of mismatching molecules). The test fails when a
//! column gets worse, or when a column without baseline entry mismatches. When
//! a column improves, the test prints a hint to tighten the baseline:
//!
//! ```text
//! FERRUM_UPDATE_PARITY_BASELINE=1 cargo test -p ferrum_core --release --test rdkit_parity
//! ```
//!
//! `FERRUM_PARITY_VERBOSE=1` prints example molecules for every deviating column.
//!
//! Deviations that cannot be closed:
//! - `Ipc`/`AvgIpc` for large, flexible molecules: RDKit evaluates the characteristic
//!   polynomial with a float64 Le Verrier-Faddeev recurrence that is numerically
//!   unstable there; its result depends on BLAS rounding (e.g. 2.2e24 for a
//!   104-atom lipid whose exact value is 3.7e21). FerrumChem uses the same
//!   recurrence and matches RDKit wherever RDKit's value is numerically stable.
//!
//! Molecules are streamed one at a time; memory use is constant.

mod common;

#[test]
fn rdkit_parity() {
    common::parity::run_parity("RDKit", "rdkit_parity_reference.csv", "rdkit_parity_baseline.tsv");
}
